{"status": "ok", "comment": "Created plugins/registry.py with the registry class implementing register, get, and run methods, including duplicate name rejection and KeyError for unknown names, to fix the missing module import error.", "file_path": "plugins/registry.py", "content": "class Registry:
    """Registry for plugin callables keyed by name."""

    def __init__(self):
        self._plugins = {}

    def register(self, name, fn):
        """Register a callable under a name. Raises ValueError if duplicate."""
        if name in self._plugins:
            raise ValueError(f"Plugin name '{name}' is already registered.")
        self._plugins[name] = fn

    def get(self, name):
        """Return the callable registered under name. Raises KeyError if unknown."""
        return self._plugins[name]

    def run(self, name, *args):
        """Run the callable registered under name with the given arguments."""
        fn = self.get(name)
        return fn(*args)


registry = Registry()
